import React, { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';

const StudentHome = () => {
  const navigate = useNavigate();

  const [menuOpen, setMenuOpen] = useState(false);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const menuRef = useRef(null);

  /* Закрытие dropdown при клике вне него */
  useEffect(() => {
    if (!menuOpen) return undefined;
    const handleOutside = (e) => {
      if (menuRef.current && !menuRef.current.contains(e.target)) {
        setMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleOutside);
    return () => document.removeEventListener('mousedown', handleOutside);
  }, [menuOpen]);

  /* Закрытие по Escape */
  useEffect(() => {
    const handleKey = (e) => {
      if (e.key === 'Escape') {
        setMenuOpen(false);
        setConfirmOpen(false);
      }
    };
    document.addEventListener('keydown', handleKey);
    return () => document.removeEventListener('keydown', handleKey);
  }, []);

  const handleLogout = () => {
    // TODO: logout() из AuthContext, когда backend будет готов
    setConfirmOpen(false);
    navigate('/');
  };

  return (
    <div className="min-h-screen w-full bg-secondary flex flex-col px-5">
      <div className="mx-auto flex w-full max-w-[480px] flex-1 flex-col">

        {/* Шапка: логотип + кнопка «...» */}
        <header className="relative flex items-center justify-between pt-6">
          <div className="flex items-center gap-3">
            {/* TODO: заменить на брендовый ассет логотипа */}
            <svg width="32" height="32" viewBox="0 0 24 24" fill="#0D0C0C" aria-hidden>
              <path d="M2 4 L22 12 L2 20 L8 12 Z" />
            </svg>
            <span className="text-2xl font-semibold text-black laptop:text-[32px]">
              Талон
            </span>
          </div>

          {/* Dropdown-контейнер */}
          <div className="relative" ref={menuRef}>
            <button
              type="button"
              aria-label="Меню"
              aria-expanded={menuOpen}
              onClick={() => setMenuOpen((v) => !v)}
              className="flex h-10 w-10 items-center justify-center rounded-lg text-black transition-colors hover:bg-gray/10"
            >
              <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor" aria-hidden>
                <circle cx="5" cy="12" r="2" />
                <circle cx="12" cy="12" r="2" />
                <circle cx="19" cy="12" r="2" />
              </svg>
            </button>

            {/* Выпадающий список */}
            {menuOpen && (
              <div className="absolute right-0 top-12 z-50 w-56 overflow-hidden rounded-xl border border-gray/15 bg-primary shadow-xl">
                <button
                  type="button"
                  onClick={() => {
                    setMenuOpen(false);
                    setConfirmOpen(true);
                  }}
                  className="flex w-full items-center gap-3 px-4 py-3 text-left text-sm text-[#F24444] transition-colors hover:bg-[rgba(242,68,68,0.08)]"
                >
                  <svg
                    width="20"
                    height="20"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    aria-hidden
                  >
                    <path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4 M10 17l5-5-5-5 M15 12H3" />
                  </svg>
                  Выйти из аккаунта
                </button>
              </div>
            )}
          </div>
        </header>

        {/* TODO: основной контент страницы студента (QR-код, баланс порций и т.д.) */}
        <div className="flex flex-1 items-center justify-center">
          <p className="text-sm text-gray">Контент студента (QR / баланс)</p>
        </div>
      </div>

      {/* Модалка подтверждения выхода */}
      {confirmOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#676565]/40 px-5">
          <div className="w-full max-w-[420px] rounded-2xl bg-primary p-6 shadow-xl">
            <div className="flex items-start justify-between">
              <h2 className="text-2xl leading-[105%] font-semibold text-black laptop:text-[32px]">
                Выход из аккаунта
              </h2>
              <button
                type="button"
                aria-label="Закрыть"
                onClick={() => setConfirmOpen(false)}
                className="p-1 text-black transition-colors hover:text-gray"
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                  <path d="M6 6l12 12M18 6L6 18" />
                </svg>
              </button>
            </div>

            <p className="mt-4 text-sm leading-[120%] text-gray">
              Вы действительно хотите выйти из аккаунта?
            </p>

            <div className="mt-6 grid grid-cols-2 gap-3">
              <button
                type="button"
                onClick={() => setConfirmOpen(false)}
                className="h-11 rounded-lg bg-gray/10 text-sm text-gray transition-colors hover:text-black"
              >
                Отмена
              </button>
              <button
                type="button"
                onClick={handleLogout}
                className="h-11 rounded-lg bg-[#F24444] text-sm font-medium text-primary transition-colors hover:bg-[#F24444]/90"
              >
                Выйти из аккаунта
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentHome;
